def encode(text):
    if text == "":
        return ""
    result = ""
    count = 1
    for i in range(1, len(text)):
        if text[i] == text[i - 1]:
            count += 1
        else:
            result = result + str(count) + text[i - 1]
            count = 1
    result = result + str(count) + text[-1]
    return result

def decode(code):
    result = ""
    number = ""
    for ch in code:
        if "0" <= ch <= "9":
            number = number + ch
        else:
            result = result + ch * int(number)
            number = ""
    return result

