SIZE = 20
stack = [""] * SIZE
top = -1

def push(item):
    global top
    if top == SIZE - 1:
        return False
    top += 1
    stack[top] = item
    return True

def pop():
    global top
    if top == -1:
        return ""
    item = stack[top]
    top -= 1
    return item

def balanced(expression):
    global top
    top = -1                      # empty the stack
    pairs = {")": "(", "]": "[", "}": "{"}
    for ch in expression:
        if ch in "([{":
            if not push(ch):
                return False      # too deeply nested
        elif ch in ")]}":
            if pop() != pairs[ch]:
                return False
    return top == -1

