data = [0] * SIZE
left = [NULL] * SIZE
right = [NULL] * SIZE
root = NULL
next_free = 0

def add_node(value):
    global root, next_free
    if next_free == SIZE:
        print("Tree full")
        return
    new = next_free
    data[new] = value
    next_free = next_free + 1
    if root == NULL:
        root = new
        return
    current = root
    while True:
        if value < data[current]:
            if left[current] == NULL:
                left[current] = new
                return
            current = left[current]
        else:
            if right[current] == NULL:
                right[current] = new
                return
            current = right[current]

def in_order(node):
