def summarise_routes(in_name, out_name):
    totals = {}
    try:
        f = open(in_name, "r")
    except FileNotFoundError:
        print("File not found")
        return -1
    for line in f:
        line = line.strip()
        if line == "":
            continue
        route, minutes = line.split(",")
        totals[route] = totals.get(route, 0) + int(minutes)
    f.close()
    ordered = sorted(totals.items(), key=lambda item: item[1], reverse=True)
    out = open(out_name, "w")
    for route, total in ordered:
        out.write(route + "," + str(total) + "\n")
    out.close()
    return len(ordered)

