def AStar(Start, Goal):
    G = {Start: 0}
    Previous = {}
    OpenList = [Start]
    Closed = []
    while len(OpenList) > 0:
        Current = OpenList[0]
        for Node in OpenList:
            if G[Node] + H[Node] < G[Current] + H[Current]:
                Current = Node
        OpenList.remove(Current)
        Closed.append(Current)
        print("Expand", Current, "f =", G[Current] + H[Current])
        if Current == Goal:
            Path = [Goal]
            while Path[0] != Start:
                Path.insert(0, Previous[Path[0]])
            return Path, G[Goal]
        for Next in Graph[Current]:
            if Next not in Closed:
                NewG = G[Current] + Graph[Current][Next]
                if Next not in G or NewG < G[Next]:
                    G[Next] = NewG
                    Previous[Next] = Current
                    if Next not in OpenList:
                        OpenList.append(Next)
    return [], -1

